#!/usr/bin/env bash
# Print the three most frequent client IPs from access.log.  With equal
# counts, retain the order in which an address first occurs in the log.
set -euo pipefail

awk '
{
    ip = $1
    if (!(ip in first_seen))
        first_seen[ip] = ++sequence
    count[ip]++
}
END {
    # Choose each rank directly so that count ties can use first_seen.
    for (rank = 1; rank <= 3; rank++) {
        winner = ""
        for (ip in count) {
            if (ip in selected)
                continue
            if (winner == "" || count[ip] > count[winner] || \
                (count[ip] == count[winner] && first_seen[ip] < first_seen[winner]))
                winner = ip
        }
        if (winner == "")
            break
        print winner
        selected[winner] = 1
    }
}
' access.log
